// src/database/drizzle/sqlite-core/effect/raw.ts
import { applyEffectWrapper } from "drizzle-orm/effect-core/query-effect";
import { entityKind } from "drizzle-orm/entity";

class SQLiteEffectRaw2 {
  execute;
  getSQL;
  action;
  dialect;
  mapBatchResult;
  static [entityKind] = "SQLiteEffectRaw";
  constructor(execute, getSQL, action, dialect, mapBatchResult) {
    this.execute = execute;
    this.getSQL = getSQL;
    this.action = action;
    this.dialect = dialect;
    this.mapBatchResult = mapBatchResult;
  }
  getQuery() {
    return { ...this.dialect.sqlToQuery(this.getSQL()), method: this.action };
  }
  mapResult(result, isFromBatch) {
    return isFromBatch ? this.mapBatchResult(result) : result;
  }
  _prepare() {
    return this;
  }
}
applyEffectWrapper(SQLiteEffectRaw2);

export { SQLiteEffectRaw2 };
